 verify_csrf();$stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($keys as $key){$stmt->execute([$key,trim($_POST[$key]??'')]);}flash('success','Website settings updated. Refresh the public website to see changes.');redirect('admin/settings.php');
}
$current=[];foreach(db()->query('SELECT setting_key,setting_value FROM settings')->fetchAll() as $row){$current[$row['setting_key']]=$row['setting_value'];}
